<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS fiches_expression_besoin (id INT AUTO_INCREMENT PRIMARY KEY,bon_commande_id INT NOT NULL,numero_feb VARCHAR(80) NOT NULL,date_disponibilite DATE NOT NULL,statut VARCHAR(30) NOT NULL DEFAULT 'a_analyser',montant_demande DECIMAL(15,2) NOT NULL DEFAULT 0,motif_rejet TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_feb_order(bon_commande_id),UNIQUE KEY uniq_feb_number(numero_feb)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
